import { log } from './log.js';

interface LightningCssError extends SyntaxError {
	fileName?: string;
	loc?: {
		line: number;
		column: number;
	};
	data?: 'ParseError' | 'ResolverError' | string;
}

const isLightningCSSError = (err: unknown): err is LightningCssError => {
	return err instanceof SyntaxError && 'fileName' in err && typeof (err as LightningCssError).fileName === 'string';
};

export const handleLightningCSSErrors = (err: unknown): void => {
	if (isLightningCSSError(err)) {
		if (err.data === 'ResolverError') {
			log.error('Could not resolve an @import. Check if the path exists or is spelled correctly.');
		} else if (err.loc) {
			log.error(['Error found at:', `\t- Line: ${err.loc.line}`, `\t- Column: ${err.loc.column}`]);
		}
	}

	throw err;
};
